styl:
.two-cta td.two-cta-cell { padding: 0 8px; }
.two-cta td.butt { border-radius: {{ radius }}px; padding: 0; }
.two-cta td.butt-a { background: {{ a_bg }}; }
.two-cta td.butt-b { background: {{ b_bg }}; }
.two-cta a.butt-link { display: block; padding: {{ padding }}; font-family: 'Helvetica', 'Arial', sans-serif; font-weight: 700; font-size: {{ font_size }}px; text-decoration: none; }
.two-cta td.butt-a a.butt-link { color: {{ a_text }}; }
.two-cta td.butt-b a.butt-link { color: {{ b_text }}; }
